const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 30);

const recent = items.filter(item => {
  const raw = item.json['Submitted At'];
  if (!raw) return false;
  const d = new Date(raw);
  return d >= cutoff;
});

const rows = recent.map(item => {
  const j = item.json;
  return `${j['Submitted At'] || ''} — ${j.Name || ''} — ${j.Phone || ''} — ${j.Interest || ''} — ${j.Source || ''}`;
}).join('\n');

const summary = recent.length
  ? `${recent.length} new lead(s) in the last 30 days:\n\n${rows}`
  : 'No new leads in the last 30 days.';

return [{ json: { count: recent.length, summary } }];
